"""The wire format, as constants the firmware parses with.

`taskgraph/emit/pack.py` decides where every byte goes. This emits those decisions
as `#define`s so the receiver reads them rather than restating them. The header
offsets in particular are the kind of number that is trivially easy to get right
once and wrong after the first field is inserted.

WHY OFFSETS AND NOT A STRUCT. The obvious alternative is a `TgHeader` struct that
the firmware casts the receive buffer to. That reintroduces the exact hazard this
project already paid for once: a struct's size and padding are the compiler's
decision, and `TgTimingSet` measured 3 bytes on AVR and 4 on the host while
compiling cleanly on both. A header read field by field at generated offsets has
no padding, no alignment and no endianness question that is not written down.
"""

from __future__ import annotations

from taskgraph.emit.pack import (
    CHUNK_BYTES,
    CRC_SIZE,
    HEADER_FIELDS,
    HEADER_SIZE,
    MAGIC,
    RX_LINE_MAX,
    SECTIONS,
    WATCH_SLOTS,
    WIRE_FORMAT,
)

BANNER = """/* GENERATED by taskgraph/codegen/wire.py — DO NOT EDIT.
 *
 * Regenerate with `taskgraph codegen`; `taskgraph codegen --check` fails CI when
 * this file is stale.
 *
 * The byte layout of an uploaded table. taskgraph/emit/pack.py is where these are
 * decided and why; this file is how the firmware reads them without restating a
 * single number.
 *
 * LITTLE-ENDIAN, and every multi-byte field is read a byte at a time. Both ends
 * are little-endian AVR/x86/ARM, so this costs nothing -- but it is written down
 * rather than assumed, and reading byte-wise means no field's alignment is the
 * compiler's decision. That is the same hazard TgTimingSet already demonstrated:
 * 3 bytes on avr-g++, 4 on clang++, clean on both.
 */
"""


def emit_header() -> str:
    out = [BANNER, "#ifndef TG_WIRE_H", "#define TG_WIRE_H", ""]
    out.append("#include <stdint.h>")
    out.append("")

    out.append("/*  First bytes on the wire. A board handed anything else -- the tail of an")
    out.append(" *  abandoned upload, a stray START line -- says so, instead of parsing")
    out.append(" *  whatever arrived as a node array. */")
    out.append(f'#define TG_TABLE_MAGIC "{MAGIC.decode()}"')
    for i, b in enumerate(MAGIC):
        out.append(f"#define TG_MAGIC_{i} 0x{b:02X}")
    out.append("")

    out.append("/*  The version of the BYTE LAYOUT, distinct from spec/vocab/template versions.")
    out.append(" *  Bumped when a section moves, is added, or changes width. A board refuses a")
    out.append(" *  format it does not know rather than guessing at offsets. */")
    out.append(f"#define TG_WIRE_FORMAT {WIRE_FORMAT}")
    out.append("")

    out.append(f"#define TG_HDR_SIZE {HEADER_SIZE}")
    out.append(f"#define TG_CRC_SIZE {CRC_SIZE}")
    out.append(f"#define TG_WATCH_SLOTS {WATCH_SLOTS}")
    out.append("")

    out.append("/*  Upload framing. TG_CHUNK_BYTES is what the host SHOULD send per line;")
    out.append(" *  the board processes whatever arrives and only requires that a line fit")
    out.append(" *  in TG_RX_LINE_MAX. Announced in CAP so the host does not have to")
    out.append(" *  compile its own copy -- the mirroring pattern this project keeps")
    out.append(" *  finding. */")
    out.append(f"#define TG_CHUNK_BYTES {CHUNK_BYTES}")
    out.append(f"#define TG_RX_LINE_MAX {RX_LINE_MAX}")
    out.append("")

    out.append("/*  Header field offsets, in bytes from the start of the table. */")
    off = len(MAGIC)
    width_name = {1: "u8", 2: "u16", 4: "u32"}
    for name, width in HEADER_FIELDS:
        if not name.startswith("_"):
            sym = f"TG_HDR_{name.upper()}"
            out.append(f"#define {sym} {off}  /* {width_name[width]} */")
        off += width
    out.append("")

    out.append("/*  Section order in the body, immediately after the header. THE RECEIVER MUST")
    out.append(" *  PARSE IN THIS ORDER. Listed as an enum so a reordering here is a compile")
    out.append(" *  error there rather than a table that loads and means something else. */")
    out.append("enum TgWireSection {")
    for i, s in enumerate(SECTIONS):
        out.append(f"  TG_SEC_{s.upper()} = {i},")
    out.append(f"  TG_SEC_COUNT = {len(SECTIONS)}")
    out.append("};")
    out.append("")

    out.append("/*  Read a little-endian field out of a byte buffer. Byte-wise on purpose:")
    out.append(" *  a cast would make the offset's alignment the compiler's problem. */")
    out.append("static inline uint16_t tgRdU16(const uint8_t *b, uint16_t off)")
    out.append("{")
    out.append("  return (uint16_t)((uint16_t)b[off] | ((uint16_t)b[off + 1] << 8));")
    out.append("}")
    out.append("")
    out.append("static inline uint32_t tgRdU32(const uint8_t *b, uint16_t off)")
    out.append("{")
    out.append("  return (uint32_t)b[off] | ((uint32_t)b[off + 1] << 8) |")
    out.append("         ((uint32_t)b[off + 2] << 16) | ((uint32_t)b[off + 3] << 24);")
    out.append("}")
    out.append("")

    out.append("#endif  /* TG_WIRE_H */")
    return "\n".join(out)
